# ---------- Google Drive থেকে অটো ইমপোর্ট (/syncdrive, /drivemap) ----------
import urllib.parse as _urlparse
import urllib.error as _urlerr
DRIVE_KEY = os.environ.get("DRIVE_API_KEY", "").strip()
_VIDEO_EXT = (".mp4", ".mkv", ".avi", ".mov", ".webm", ".m4v", ".ts")
_CUT = re.compile(r"\b((?:19|20)\d{2}|2160p|1080p|720p|480p|360p|4k|s\d{1,2}[ ._-]*e\d{1,3}|bluray|blu-ray|brrip|bdrip|"
                  r"webrip|web-dl|webdl|hdrip|hdtc|hdcam|dvdrip|remux|hindi|english|dual|multi|org|hevc|x264|x265|10bit|esubs?|v2)\b", re.I)

def parse_drive_name(name):
    stem = name.rsplit(".", 1)[0] if name.lower().endswith(_VIDEO_EXT) else name
    norm = re.sub(r"[\[\](){}]", " ", stem)
    norm = re.sub(r"[_.]+", " ", norm)
    norm = re.sub(r"\s+", " ", norm).strip()
    m_se = re.search(r"\bs(\d{1,2})[ ._-]*e(\d{1,3})\b", norm, re.I)
    m_q = re.search(r"\b(2160|1080|720|480|360)p\b", norm, re.I)
    quality = (m_q.group(1) + "p") if m_q else ("4K" if re.search(r"\b4k\b", norm, re.I) else "Original")
    cut = next((m for m in _CUT.finditer(norm) if m.start() > 0), None)
    base = norm[:cut.start()] if cut else norm
    base = base.strip(" -")
    year = None
    if not m_se:
        ym = next((m for m in re.finditer(r"\b((?:19|20)\d{2})\b", norm) if m.start() >= len(base)), None)
        year = ym.group(1) if ym else None
    title = base + (f" {year}" if year else "")
    if re.search(r"\bhindi\b", norm, re.I):
        title += " Hindi"
    return {
        "title": title.strip() or stem,
        "series": bool(m_se),
        "season": f"Season {int(m_se.group(1))}" if m_se else None,
        "episode": f"Episode {int(m_se.group(2))}" if m_se else None,
        "quality": quality,
    }

def _drive_api(path, params):
    params = dict(params)
    params["key"] = DRIVE_KEY
    url = "https://www.googleapis.com/drive/v3/" + path + "?" + _urlparse.urlencode(params)
    with _urlreq.urlopen(url, timeout=25) as r:
        return json.loads(r.read().decode("utf-8"))

def _drive_scan(root_id, max_folders=600):
    info = _drive_api("files/" + root_id, {"fields": "name", "supportsAllDrives": "true"})
    root_name = info.get("name", root_id)
    files, queue, seen = [], [(root_id, [root_name])], 0
    while queue:
        fid, path = queue.pop(0)
        seen += 1
        if seen > max_folders:
            break
        token = None
        while True:
            p = {"q": f"'{fid}' in parents and trashed=false",
                 "fields": "nextPageToken,files(id,name,mimeType)", "pageSize": "1000",
                 "supportsAllDrives": "true", "includeItemsFromAllDrives": "true"}
            if token:
                p["pageToken"] = token
            data = _drive_api("files", p)
            for f in data.get("files", []):
                mt = f.get("mimeType", "")
                if mt == "application/vnd.google-apps.folder":
                    queue.append((f["id"], path + [f["name"]]))
                elif mt.startswith("video/") or f["name"].lower().endswith(_VIDEO_EXT):
                    files.append((path, f["name"], f["id"]))
            token = data.get("nextPageToken")
            if not token:
                break
    return root_name, files

def _existing_drive_ids():
    ids = set()
    def walk(n):
        if isinstance(n, dict):
            for v in n.values():
                walk(v)
        elif isinstance(n, str):
            m = re.search(r"/d/([\w-]{20,})|[?&]id=([\w-]{20,})", n)
            if m:
                ids.add(m.group(1) or m.group(2))
    walk(db)
    return ids

def _norm_title(x, strip_year=False):
    x = x.lower()
    if strip_year:
        x = re.sub(r"\b(19|20)\d{2}\b", " ", x)
    x = re.sub(r"\b(hindi|dubbed|dual audio|full movie|the)\b", " ", x)
    return re.sub(r"[^a-z0-9\u0980-\u09ff]+", "", x)

def _drive_category_for(path):
    if not bot_settings.get("drive_auto_category"):
        return None
    dm = bot_settings.get("drive_map", {})
    for i in range(len(path), 0, -1):
        key = "/".join(path[:i]).lower()
        if key in dm:
            return dm[key]["cat"]
    return None

def _tree_add(cat, title, nested_path):
    node = category_tree
    for seg in cat:
        node = node.setdefault(seg, {})
    node.setdefault("_titles", [])
    if any(isinstance(e, dict) and e.get("title") == title and e.get("path", []) == nested_path for e in node["_titles"]):
        return False
    display = title if not nested_path else " - ".join(nested_path)
    node["_titles"].append({"title": title, "path": nested_path, "display": display})
    return True

def _category_paths(node=None, trail=None, out=None):
    node = category_tree if node is None else node
    trail = trail or []
    out = [] if out is None else out
    for k, v in node.items():
        if k == "_titles" or not isinstance(v, dict):
            continue
        out.append(trail + [k])
        _category_paths(v, trail + [k], out)
    return out

def _existing_cat_of(title):
    found = []
    def walk(node, trail):
        for k, v in node.items():
            if k == "_titles":
                if any(isinstance(e, dict) and e.get("title") == title for e in v):
                    found.append(trail)
            elif isinstance(v, dict):
                walk(v, trail + [k])
    walk(category_tree, [])
    return found[0] if found else None

async def _ai_classify(titles):
    """নতুন টাইটেলগুলোর জন্য: (১) আগের একই টাইটেল থাকলে সেই নাম, (২) সঠিক ক্যাটাগরি ফোল্ডার — Gemini বেছে দেয়।"""
    existing = list(db.keys())[:900]
    paths = [" / ".join(pp) for pp in _category_paths()][:200]
    system_text = (
        "You organize movies/series for a Telegram bot. For EACH new title return: "
        "(1) \"canonical\": if it is the same movie/series as one in EXISTING_TITLES (ignore words like Marvels, The, punctuation, year formatting) "
        "return that existing title EXACTLY as written; otherwise return the new title unchanged. "
        "(2) \"category\": a list of folder names. Prefer an EXACT existing path from CATEGORY_PATHS split into a list "
        "(e.g. a Marvel movie -> [\"Hollywood\",\"Marvel\", ...] using the closest existing path). If nothing fits, create a sensible new path "
        "reusing existing top-level names (Hollywood, Bollywood, South Movies, Web Series, Songs...). Web series go under Web Series. Max 4 levels. "
        "Reply JSON only: {\"items\":[{\"title\":string,\"canonical\":string,\"category\":[string]}]}.\n"
        f"CATEGORY_PATHS: {' | '.join(paths)}\n"
        f"EXISTING_TITLES: {' || '.join(existing)}"
    )
    contents = [{"role": "user", "parts": [{"text": "NEW TITLES:\n" + "\n".join(titles)}]}]
    data = await asyncio.wait_for(asyncio.get_running_loop().run_in_executor(
        None, _gemini_call, system_text, contents, 6000), timeout=75)
    out = {}
    low = {k.lower(): k for k in db}
    for it in data.get("items", []) or []:
        t0 = str(it.get("title", "")).strip()
        can = str(it.get("canonical", "")).strip() or t0
        can = low.get(can.lower(), can)
        cat = [str(x).strip() for x in (it.get("category") or []) if str(x).strip()][:4]
        if t0:
            out[t0] = (can, cat or None)
    return out

