def _folder_id_from(text):
    m = re.search(r"folders/([\w-]{10,})", text) or re.search(r"[?&]id=([\w-]{10,})", text)
    if m:
        return m.group(1)
    return text if re.fullmatch(r"[\w-]{15,}", text) else None

async def sync_drive(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/syncdrive <ফোল্ডার লিংক> [আরও লিংক] — স্ক্যান করে প্রিভিউ দেখায়, OK দিলে বসায়।"""
    if update.effective_user.id != ADMIN_ID:
        return
    msg = update.message
    if not DRIVE_KEY:
        await msg.reply_text("❌ Render-এ DRIVE_API_KEY নেই।")
        return
    args = (msg.text or "").split()[1:]
    ids = [x for x in (_folder_id_from(a) for a in args) if x]
    if not ids:
        await msg.reply_text("ফরম্যাট:\n/syncdrive https://drive.google.com/drive/folders/XXXX")
        return
    await msg.reply_text("⏳ ড্রাইভ স্ক্যান হচ্ছে, একটু অপেক্ষা করো...")
    existing = _existing_drive_ids()
    plan, seen_keys = [], set()
    skipped_old = dup = 0
    try:
        for rid in ids:
            root_name, files = await asyncio.to_thread(_drive_scan, rid)
            for path, name, fid in files:
                if fid in existing:
                    skipped_old += 1
                    continue
                info = parse_drive_name(name)
                key = (info["title"].lower(), info["season"], info["episode"], info["quality"])
                if key in seen_keys:
                    dup += 1
                    continue
                seen_keys.add(key)
                info.update({"link": f"https://drive.google.com/file/d/{fid}/view", "cat": _drive_category_for(path), "name": name})
                plan.append(info)
    except _urlerr.HTTPError as e:
        body = ""
        try:
            body = e.read().decode("utf-8", "ignore")[:300]
        except Exception:
            pass
        hint = "ফোল্ডার 'Anyone with the link' করা আছে? Drive API চালু?" if e.code in (403, 404) else ""
        await msg.reply_text(f"❌ Drive error {e.code}. {hint}\n{body}")
        return
    except Exception as e:
        await msg.reply_text(f"❌ ত্রুটি: {e}")
        return
    # আগের টাইটেলের সাথে নাম মিললে (সাল/Hindi/চিহ্ন বাদ দিয়ে) সেই টাইটেলেই বসানো
    exist_map = {}
    for k in db:
        exist_map.setdefault(_norm_title(k, isinstance(db[k], dict) and not is_leaf_level(db[k])), k)
    for it in plan:
        ek = exist_map.get(_norm_title(it["title"], bool(it.get("series"))))
        if ek and ek != it["title"]:
            it["title"] = ek
    # একই সিরিজের কিছু ফাইলে Hindi লেখা, কিছুতে নেই: সব এক টাইটেলে মেলানো
    hindi_bases = {it["title"][:-6].lower() for it in plan if it["series"] and it["title"].endswith(" Hindi")}
    merged, seen3 = [], set()
    for it in plan:
        if it["series"] and not it["title"].endswith(" Hindi") and it["title"].lower() in hindi_bases:
            it["title"] += " Hindi"
        k3 = (it["title"].lower(), it["season"], it["episode"], it["quality"])
        if k3 in seen3:
            dup += 1
            continue
        seen3.add(k3)
        merged.append(it)
    plan = merged
    if not plan:
        await msg.reply_text(f"নতুন কিছু নেই। (আগে থেকেই আছে: {skipped_old})")
        return
    ai_used = False
    todo = sorted({it["title"] for it in plan if not it["cat"]})
    if todo and ai_enabled() and bot_settings.get("drive_auto_category"):
        try:
            await msg.reply_text("🤖 এআই ক্যাটাগরি ও নাম ঠিক করছে...")
            res = await _ai_classify(todo)
            seen2, newplan = set(), []
            for it in plan:
                if not it["cat"] and it["title"] in res:
                    can, cat = res[it["title"]]
                    it["title"] = can
                    it["cat"] = _existing_cat_of(can) or cat
                    it["ai"] = True
                    ai_used = True
                k2 = (it["title"].lower(), it["season"], it["episode"], it["quality"])
                if k2 in seen2:
                    dup += 1
                    continue
                seen2.add(k2)
                newplan.append(it)
            plan = newplan
        except Exception as e:
            await msg.reply_text(f"⚠️ এআই ব্যর্থ ({str(e)[:80]}), ক্যাটাগরি ছাড়াই দেখাচ্ছি।")
    context.bot_data["drive_plan"] = plan
    groups = {}
    for it in plan:
        groups.setdefault((it["title"], tuple(it["cat"] or ())), []).append(it)
    lines = []
    for (title, cat), its in groups.items():
        if its[0]["series"]:
            sc = {}
            for it in its:
                sc[it["season"]] = sc.get(it["season"], 0) + 1
            detail = ", ".join(f"S{k.split()[-1]}:{v}ep" for k, v in sc.items()) + f" {its[0]['quality']}"
        else:
            detail = ", ".join(sorted({i["quality"] for i in its}))
        lines.append(f"• {title} ({detail}) → {' / '.join(cat) if cat else '🔎 শুধু সার্চে (ক্যাটাগরিতে যাবে না)'}{' 🤖' if its[0].get('ai') else ''}")
    header = (f"📋 প্রিভিউ\n🆕 নতুন ফাইল: {len(plan)} | ⏭ আগে থেকেই আছে: {skipped_old} | 🔁 ডুপ্লিকেট: {dup}\n"
              f"🎬 টাইটেল: {len(groups)}\n\n")
    chunks, cur = [], header
    for ln in lines:
        if len(cur) + len(ln) > 3500:
            chunks.append(cur)
            cur = ""
        cur += ln + "\n"
    chunks.append(cur)
    for c in chunks[:-1]:
        await msg.reply_text(c)
    kb = InlineKeyboardMarkup([[InlineKeyboardButton("✅ বসাও", callback_data="sd_ok"),
                                InlineKeyboardButton("❌ বাতিল", callback_data="sd_no")]])
    await msg.reply_text(chunks[-1], reply_markup=kb)

async def drive_confirm(update: Update, context: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    if q.from_user.id != ADMIN_ID:
        await q.answer()
        return
    await q.answer()
    plan = context.bot_data.pop("drive_plan", None)
    if q.data == "sd_no" or not plan:
        await q.message.reply_text("বাতিল (বা প্রিভিউ পুরনো, আবার /syncdrive দাও)।")
        return
    added = skipped = 0
    new_titles, nocat = set(), set()
    now = datetime.now(timezone.utc).isoformat()
    for it in plan:
        title = find_existing_title(it["title"])
        cur = db.get(title)
        if it["series"]:
            if cur and is_leaf_level(cur):
                skipped += 1
                continue
            node = db.setdefault(title, {}).setdefault(it["season"], {})
            if node and is_leaf_level(node):
                skipped += 1
                continue
            if it["quality"] in node.get(it["episode"], {}):
                skipped += 1
                continue
            node.setdefault(it["episode"], {})[it["quality"]] = it["link"]
            nested = [it["season"]]
        else:
            if cur and not is_leaf_level(cur):
                skipped += 1
                continue
            if it["quality"] in (cur or {}):
                skipped += 1
                continue
            db.setdefault(title, {})[it["quality"]] = it["link"]
            nested = []
        added += 1
        if title not in new_titles:
            new_titles.add(title)
            title_meta.setdefault(title, {})["added_at"] = now
        if it["cat"]:
            _tree_add(it["cat"], title, nested)
        else:
            nocat.add(title)
    normalize_db()
    save_state("content", DB_FILE, db)
    save_state("meta", META_FILE, title_meta)
    save_state("categories", CATEGORY_FILE, category_tree)
    await q.message.reply_text(
        f"✅ হয়ে গেছে!\n🆕 যোগ: {added} ফাইল ({len(new_titles)} টাইটেল)\n⏭ বাদ: {skipped}\n"
        f"🔎 সার্চে পাওয়া যাবে, ক্যাটাগরিতে যোগ হয়নি।")
    lst = []
    seen_l = set()
    for it in plan:
        line = it["title"] + (f" | {it['season']}" if it["series"] else "")
        if line not in seen_l:
            seen_l.add(line)
            lst.append(line)
    if lst:
        await _send_chunks(q.message, "📋 নতুন যোগ হওয়া তালিকা (কপি করে Gemini-কে দাও):\n\n" + "\n".join(lst))
    for t_ in list(new_titles)[:30]:
        try:
            await notify_fulfilled_requests(context, t_)
        except Exception:
            pass

# ---------- সার্ভিস মনিটর: কোনো সার্ভিস বন্ধ হলে অ্যাডমিনকে মেসেজ ----------
_svc_state = {}
_bg_tasks = []

def _http_ok(url, headers=None, timeout=12):
    req = _urlreq.Request(url, headers=headers or {})
    with _urlreq.urlopen(req, timeout=timeout) as r:
        return r.status < 400

def _chk_gemini():
    if not GEMINI_KEY:
        return None
    return _http_ok("https://generativelanguage.googleapis.com/v1beta/models?pageSize=1", {"x-goog-api-key": GEMINI_KEY})

def _chk_tmdb():
    if not TMDB_KEY:
        return None
    return _http_ok(f"https://api.themoviedb.org/3/configuration?api_key={TMDB_KEY}")

def _chk_tmdb_img():
    if not TMDB_KEY:
        return None
    try:
        return _http_ok("https://image.tmdb.org/t/p/w92/")
    except _urlerr.HTTPError as e:
        return e.code < 500   # ৪০৪ মানে সার্ভার আছে

def _chk_mongo():
    if not mongo_client:
        return None
    mongo_client.admin.command("ping")
    return True

def _chk_drive():
    if not DRIVE_KEY:
        return None
    return _http_ok("https://www.googleapis.com/discovery/v1/apis/drive/v3/rest")

_SERVICES = {
    "🤖 Gemini এআই": _chk_gemini,
    "🖼 পোস্টার সার্ভার (TMDB)": _chk_tmdb,
    "🖼 পোস্টার ছবির সার্ভার": _chk_tmdb_img,
    "🗄 ডাটাবেস (MongoDB)": _chk_mongo,
    "📁 Google Drive": _chk_drive,
}

def _probe(fn):
    try:
        r = fn()
        if r is None:
            return "skip"
        return None if r else "সাড়া নেই"
    except _urlerr.HTTPError as e:
        return {429: "কোটা শেষ (HTTP 429)", 401: "চাবি ভুল (HTTP 401)", 403: "চাবি/অনুমতি সমস্যা (HTTP 403)"}.get(e.code, f"HTTP {e.code}")
    except Exception as e:
        return type(e).__name__

async def health_monitor(bot):
    await asyncio.sleep(90)
    while True:
        for name, fn in _SERVICES.items():
            try:
                reason = await asyncio.to_thread(_probe, fn)
            except Exception as e:
                reason = type(e).__name__
            if reason == "skip":
                continue
            st = _svc_state.setdefault(name, {"ok": True, "fails": 0})
            if reason:
                st["fails"] += 1
                if st["fails"] >= 2 and st["ok"]:
                    st["ok"] = False
                    try:
                        await bot.send_message(ADMIN_ID, f"🚨 {name} বন্ধ বা সমস্যায় আছে!\n⚠️ কারণ: {reason}")
                    except Exception:
                        pass
            else:
                st["fails"] = 0
                if not st["ok"]:
                    st["ok"] = True
                    try:
                        await bot.send_message(ADMIN_ID, f"✅ {name} আবার ঠিক হয়ে গেছে।")
                    except Exception:
                        pass
        await asyncio.sleep(300)

# ---------- একসাথে অনেক কমান্ড (প্রতি লাইনে একটা) ----------
def _command_table(context):
    table = {}
    for grp in context.application.handlers.values():
        for h in grp:
            if isinstance(h, CommandHandler):
                for c in h.commands:
                    table.setdefault(c, h.callback)
    return table

async def _run_lines(update, context, cmd_lines, quiet=False, pause=0.4):
    """প্রতি লাইনের কমান্ড এক এক করে চালায়। ফেরত: [(লাইন, উত্তর বা ত্রুটি)]"""
    import telegram as _tg
    table = _command_table(context)
    results = []
    captured = []
    orig_reply = _tg.Message.reply_text
    if quiet:
        async def _fake_reply(self, text=None, *a, **k):
            captured.append(str(text))
            return None
        _tg.Message.reply_text = _fake_reply
    try:
        for ln in cmd_lines:
            m = re.match(r"/(\w+)(?:@\w+)?(.*)$", ln, re.S)
            cb = table.get(m.group(1).lower()) if m else None
            if not cb:
                results.append((ln, "❓ অচেনা কমান্ড"))
                continue
            d = update.to_dict()
            d["message"]["text"] = f"/{m.group(1)}{m.group(2)}"
            for k in ("entities", "document", "caption", "caption_entities"):
                d["message"].pop(k, None)
            new_update = Update.de_json(d, context.bot)
            context.args = m.group(2).split()
            del captured[:]
            try:
                await cb(new_update, context)
                results.append((ln, (captured[0].split("\n")[0] if captured else "ok")))
            except ApplicationHandlerStop:
                results.append((ln, "ok"))
            except Exception as e:
                results.append((ln, f"⚠️ ত্রুটি: {str(e)[:100]}"))
            await asyncio.sleep(pause if not quiet else 0.05)
    finally:
        _tg.Message.reply_text = orig_reply
    return results

async def bulk_commands(update: Update, context: ContextTypes.DEFAULT_TYPE):
    msg = update.message
    if not msg or not msg.text or not update.effective_user or update.effective_user.id != ADMIN_ID:
        return
    if not msg.text.lstrip().startswith("/"):
        return
    cmd_lines = [l.strip() for l in msg.text.split("\n") if l.strip().startswith("/")]
    if len(cmd_lines) < 2:
        return
    res = await _run_lines(update, context, cmd_lines)
    bad = sum(1 for _, r in res if r.startswith(("❓", "⚠️")))
    await msg.reply_text(f"📦 {len(res) - bad}টা কমান্ড চালানো হয়েছে" + (f" | ❌ {bad}টা হয়নি" if bad else ""))
    chat = update.effective_chat
    if chat:
        task = typing_tasks.pop(chat.id, None)
        if task:
            task.cancel()
    raise ApplicationHandlerStop

async def run_commands_file(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """অ্যাডমিন .txt ফাইল পাঠালে তার প্রতি লাইনের কমান্ড চলে, শেষে রিপোর্ট ফাইল ফেরত আসে।"""
    msg = update.message
    if not msg or not msg.document or update.effective_user.id != ADMIN_ID:
        return
    name = (msg.document.file_name or "").lower()
    if not name.endswith(".txt"):
        return
    f = await msg.document.get_file()
    raw = bytes(await f.download_as_bytearray()).decode("utf-8", "ignore")
    cmd_lines = [l.strip() for l in raw.splitlines() if l.strip().startswith("/")][:1500]
    if not cmd_lines:
        await msg.reply_text("ফাইলে / দিয়ে শুরু কোনো কমান্ড নেই।")
        return
    await msg.reply_text(f"⏳ {len(cmd_lines)}টা কমান্ড চলছে...")
    res = await _run_lines(update, context, cmd_lines, quiet=True)
    bad = [(l, r) for l, r in res if r.startswith(("❓", "⚠️")) or any(w in r for w in ("Not found", "পাওয়া যায়নি", "Format", "format", "नहीं मिला", "Need at least"))]
    report = "\n".join(f"{'FAIL' if (l, r) in bad else 'OK  '} | {l[:120]} | {r}" for l, r in res)
    await msg.reply_document(document=io.BytesIO(report.encode("utf-8")), filename="report.txt",
                             caption=f"✅ চলেছে: {len(res) - len(bad)} | ❌ হয়নি: {len(bad)}")

